{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Codeine, the closest analogue (Morgan 0.5469), has an absolute oral bioavailability of 42–71% in healthy volunteers, directly supporting F ≥20% for the query's 3-methoxy morphinan scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Codeine systemic availability after oral administration was about 90% in healthy adults, further supporting high oral bioavailability for the closely related query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Codeine sulfate showed 80.5% oral bioavailability in healthy subjects, confirming that the 3-methoxy morphinan core is well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Ethylmorphine, a close 3-alkoxy analogue, had a median systemic availability of 74% (range 54–92%), supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Samidorphan, a structurally related morphinan with a ketone, had 69% absolute oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Naltrexone had only 5–6% oral bioavailability, but this low-F result transfers poorly because the query lacks naltrexone's free phenol and N-cyclopropylmethyl substituents and is much closer to codeine.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The closest and most transferable evidence (codeine, codeine sulfate, ethylmorphine, samidorphan) consistently shows oral bioavailability well above 20%, while low-F examples are structurally more distant and carry liabilities absent in the query. Therefore predict high F (≥20%).",
  "evidence_gaps": [
    "No direct hydrocodone bioavailability measurement is present in the evidence set; prediction relies on close analogues.",
    "Human F may be affected by CYP2D6/CYP3A4 metabolism and formulation, but these are not expected to drop F below 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

